cat > /app/output/styles.css << 'EOF'
:root {
  --bg: #0d1117;
  --bg-elev: #111826;
  --bg-elev-2: #0f1724;
  --text: #e6edf3;
  --muted: #9da7b4;
  --line: rgba(148, 163, 184, 0.22);
  --line-strong: rgba(125, 211, 252, 0.4);
  --accent: #22d3ee;
  --accent-2: #34d399;
  --danger: #fb7185;
  --radius: 14px;
  --radius-sm: 10px;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  --container: 1200px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: radial-gradient(circle at 20% -10%, #122033 0%, var(--bg) 48%);
  color: var(--text);
  line-height: 1.5;
}

a { color: inherit; text-decoration: none; }
.container { width: min(var(--container), 92vw); margin: 0 auto; }

.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(10px);
  background: rgba(13, 17, 23, 0.78);
}
.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 14px 0;
}
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; }
.logo {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow: 0 0 0 1px rgba(255,255,255,.14) inset;
}
.nav-links { display: flex; gap: 8px; flex-wrap: wrap; }
.nav-links a {
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid transparent;
  color: var(--muted);
  font-size: 0.95rem;
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text);
  border-color: var(--line);
  background: rgba(255,255,255,0.02);
}

.hero { padding: 56px 0 24px; }
.eyebrow {
  color: var(--accent);
  text-transform: uppercase;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  font-weight: 600;
}
h1 { margin: 10px 0 14px; font-size: clamp(2rem, 5vw, 3.2rem); line-height: 1.12; }
.lead { color: var(--muted); max-width: 72ch; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 24px; }
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: transparent;
}
.btn.primary {
  border-color: transparent;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #021018;
}
.btn:hover { transform: translateY(-1px); }

.section { padding: 20px 0 34px; }
.section h2 { margin: 0 0 8px; font-size: 1.45rem; }
.section p.section-intro { color: var(--muted); margin: 0 0 18px; }

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}
.card {
  background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
}
.card h3 { margin: 0 0 6px; }
.card p { margin: 0 0 14px; color: var(--muted); }
.card .badge {
  display: inline-flex;
  font-size: .75rem;
  padding: 4px 8px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  color: var(--accent);
  margin-bottom: 10px;
}

.cli-shell {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg-elev);
}
.cli-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}
.tabs { display: inline-flex; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }
.tab {
  background: transparent;
  color: var(--muted);
  border: 0;
  border-right: 1px solid var(--line);
  padding: 8px 12px;
  cursor: pointer;
  font-family: inherit;
}
.tab:last-child { border-right: 0; }
.tab.active { background: rgba(34,211,238,.15); color: var(--text); }

code, pre {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}
.codeblock {
  margin: 0;
  background: #0a0f16;
  border-top: 1px solid var(--line);
  color: #d3f9ff;
  padding: 14px 16px;
  overflow-x: auto;
}

.accordion-item { border-top: 1px solid var(--line); }
.accordion-btn {
  width: 100%;
  background: transparent;
  border: 0;
  color: var(--text);
  text-align: left;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  font-weight: 600;
}
.accordion-btn span { color: var(--muted); font-size: .9rem; font-weight: 500; }
.accordion-panel {
  display: none;
  padding: 0 16px 16px;
}
.accordion-item.open .accordion-panel { display: block; }

.docs-layout {
  display: grid;
  grid-template-columns: 280px minmax(0,1fr);
  gap: 18px;
  padding: 24px 0 50px;
}
.sidebar {
  border: 1px solid var(--line);
  background: var(--bg-elev-2);
  border-radius: var(--radius);
  padding: 14px;
  position: sticky;
  top: 76px;
  height: fit-content;
  transition: width .22s ease, padding .22s ease, opacity .22s ease;
}
.sidebar-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.sidebar-header h3 { margin: 0; font-size: 1rem; }
.icon-btn {
  border: 1px solid var(--line);
  background: transparent;
  color: var(--muted);
  border-radius: 8px;
  padding: 6px 8px;
  cursor: pointer;
}
.sidebar ul { list-style: none; margin: 0; padding: 0; }
.sidebar li a {
  display: block;
  border-radius: 8px;
  padding: 8px 10px;
  color: var(--muted);
  font-size: .95rem;
}
.sidebar li a:hover, .sidebar li a.active { color: var(--text); background: rgba(255,255,255,.03); }
.docs-main .block {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255,255,255,0.01);
  padding: 18px;
  margin-bottom: 14px;
}
.docs-main h1 { font-size: clamp(1.6rem, 4vw, 2.25rem); margin-top: 0; }
.list-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 12px;
}
.small-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255,255,255,0.01);
  padding: 12px;
}
.small-card h4 { margin: 0 0 6px; }
.small-card p { margin: 0; color: var(--muted); font-size: .93rem; }

.docs-layout.sidebar-collapsed { grid-template-columns: 64px minmax(0,1fr); }
.docs-layout.sidebar-collapsed .sidebar { padding: 10px; }
.docs-layout.sidebar-collapsed .sidebar-header h3,
.docs-layout.sidebar-collapsed .sidebar li a span { display: none; }
.docs-layout.sidebar-collapsed .sidebar li a { text-align: center; padding: 8px 6px; }

footer { color: var(--muted); font-size: .9rem; padding: 24px 0 40px; }

@media (max-width: 1000px) {
  .card-grid, .list-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
}
@media (max-width: 820px) {
  .docs-layout { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .docs-layout .sidebar { display: none; }
  .docs-layout.sidebar-collapsed .sidebar { display: none; }
}
@media (max-width: 640px) {
  .card-grid, .list-grid { grid-template-columns: 1fr; }
  .topbar-inner { flex-direction: column; align-items: flex-start; }
}
EOF

cat > /app/output/script.js << 'EOF'
(function () {
  const tabButtons = document.querySelectorAll('[data-tab]');
  const tabCode = document.querySelector('[data-cli-code]');

  const commands = {
    npm: 'npm install -g @commerceforge/cli@latest',
    yarn: 'yarn global add @commerceforge/cli@latest',
    pnpm: 'pnpm add -g @commerceforge/cli@latest'
  };

  function setTab(tab) {
    tabButtons.forEach((btn) => btn.classList.toggle('active', btn.dataset.tab === tab));
    if (tabCode) tabCode.textContent = commands[tab] || commands.npm;
  }

  tabButtons.forEach((btn) => {
    btn.addEventListener('click', () => setTab(btn.dataset.tab));
  });

  const accordionItems = document.querySelectorAll('.accordion-item');
  accordionItems.forEach((item) => {
    const btn = item.querySelector('.accordion-btn');
    if (!btn) return;
    btn.addEventListener('click', () => {
      accordionItems.forEach((other) => {
        if (other !== item) other.classList.remove('open');
      });
      item.classList.toggle('open');
    });
  });

  const docsLayout = document.querySelector('.docs-layout');
  const sidebarToggle = document.querySelector('[data-sidebar-toggle]');
  if (docsLayout && sidebarToggle) {
    sidebarToggle.addEventListener('click', () => {
      docsLayout.classList.toggle('sidebar-collapsed');
    });
  }

  if (tabCode && tabCode.textContent.trim() === '') setTab('npm');
})();
EOF

